// Independent wire samples: expected text is not generated by the codec under test.
var outputSamples = []struct {
	encoding   OutputEncoding
	wire, text string
}{
	{EncodingUTF8, "\xe4\xb8\xad", "中"},
	{EncodingGB2312, "\xd6\xd0\x81\x40", "中丂"}, // Deliberate GBK compatibility.
	{EncodingGBK, "\xd6\xd0\x81\x40", "中丂"},
	{EncodingGB18030, "\x90\x30\x81\x30", "𐀀"},
	{EncodingBig5, "\xa4\xa4\x88\x62", "中Ê\u0304"},
	{EncodingShiftJIS, "\x93\xfa\x96\x7b\xb6", "日本ｶ"},
	{EncodingEUCJP, "\xc6\xfc\x8e\xb6\x8f\xa2\xaf", "日ｶ˘"},
	{EncodingEUCKR, "\xc7\xd1\x81\x41", "한갂"},
	{EncodingWindows1252, "\x80\xe9", "€é"},
	{EncodingWindows1250, "\xa3\xb9", "Łą"},
	{EncodingISO8859_1, "\xa3\xe9", "£é"},
	{EncodingISO8859_2, "\xa3\xb1", "Łą"},
	{EncodingISO8859_15, "\xa4\xbc", "€Œ"},
	{EncodingWindows1251, "\xdf\xff", "Яя"},
	{EncodingKOI8R, "\xf1\xd1", "Яя"},
	{EncodingKOI8U, "\xa4\xb4", "єЄ"},
	{EncodingISO8859_5, "\xcf\xef", "Яя"},
	{EncodingCP437, "\x82\xb3", "é│"},
	{EncodingCP850, "\x82\x9b", "éø"},
	{EncodingCP866, "\x9f\xef", "Яя"},
}

func TestOutputEncodingsRegistry(t *testing.T) {
	want := make([]OutputEncoding, len(outputSamples))
	for i, tc := range outputSamples {
		want[i] = tc.encoding
	}
	got := OutputEncodings()
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("registry: %v want %v", got, want)
	}
	got[0] = "invalid"
	if !reflect.DeepEqual(OutputEncodings(), want) {
		t.Fatal("caller mutated registry")
	}
}

func TestOutputEncodingKnownBytesPartitions(t *testing.T) {
	for _, tc := range outputSamples {
		t.Run(string(tc.encoding), func(t *testing.T) {
			data := []byte("A" + tc.wire + "Z")
			for mask := 0; mask < 1<<(len(data)-1); mask++ {
				term := New(40, 1)
				setEncoding(t, term, tc.encoding)
				start := 0
				for i := range data {
					if i == len(data)-1 || mask&(1<<i) != 0 {
						if n, err := term.Write(data[start : i+1]); err != nil || n != i+1-start {
							t.Fatalf("write: %d %v", n, err)
						}
						start = i + 1
					}
				}
				if got := term.ScreenText(); got != "A"+tc.text+"Z" {
					t.Fatalf("partition %d: %q want %q", mask, got, "A"+tc.text+"Z")
				}
			}
		})
	}
}

func TestOutputEncodingStylesCopySearch(t *testing.T) {
	for _, tc := range outputSamples {
		t.Run(string(tc.encoding), func(t *testing.T) {
			term := New(40, 1)
			setEncoding(t, term, tc.encoding)
			if _, err := term.Write([]byte("\x1b[1;31m" + tc.wire + "\x1b[0m!")); err != nil {
				t.Fatal(err)
			}
			if c := cell(term, 0, 0); c.FG != Indexed(1) || c.Attr != Bold {
				t.Fatalf("style: %+v", c)
			}
			if got := term.Text(Pos{0, 0}, Pos{0, 39}); got != tc.text+"!" {
				t.Fatalf("copy: %q", got)
			}
			if matches := term.Find(tc.text, false); len(matches) != 1 || matches[0].Col != 0 {
				t.Fatalf("search: %+v", matches)
			}
			if c := cell(term, term.cur.x-1, 0); c.Attr != 0 {
				t.Fatalf("reset: %+v", c)
			}
		})
	}
}

func TestOutputEncodingProtocolsRaw(t *testing.T) {
	for _, selected := range OutputEncodings()[1:] {
		t.Run(string(selected), func(t *testing.T) {
			term, got, drops := collect(t)
			setEncoding(t, term, selected)
			rawTitle := "\x81\x40\xff"
			data := "\x1b]2;" + rawTitle + "\x1b\\\x1b]7;file://host/home/中文\x07" +
				"\x1b]52;c;" + b64("中文📋") + "\x07" + tmuxWrap("\x1b]52;c;"+b64("透传")+"\x07") +
				"\x1bPignored\x81\x40\x1b\\ok"
			for _, b := range []byte(data) {
				if _, err := term.Write([]byte{b}); err != nil {
					t.Fatal(err)
				}
			}
			if term.Title() != rawTitle || term.Cwd() != "/home/中文" {
				t.Fatalf("raw OSC: title %q cwd %q", term.Title(), term.Cwd())
			}
			if len(*got) != 2 || (*got)[0].data != "中文📋" || (*got)[1].data != "透传" || *drops != 0 {
				t.Fatalf("clipboard: %+v drops %d", *got, *drops)
			}
			if term.ScreenText() != "ok" {
				t.Fatalf("protocol leak: %q", term.ScreenText())
			}
		})
	}
}

var outputFragments = []struct {
	encoding OutputEncoding
	fragment string
}{
	{EncodingUTF8, "\xe4\xb8"}, {EncodingGB2312, "\x81"}, {EncodingGBK, "\x81"},
	{EncodingGB18030, "\x81\x30\x81"}, {EncodingBig5, "\x88"},
	{EncodingShiftJIS, "\x93"}, {EncodingEUCJP, "\x8f\xa2"}, {EncodingEUCKR, "\x81"},
}

func TestOutputEncodingFragmentBoundaries(t *testing.T) {
	for _, tc := range outputFragments {
		for _, reset := range []bool{false, true} {
			term := New(40, 1)
			setEncoding(t, term, tc.encoding)
			term.WriteString("old" + tc.fragment)
			setEncoding(t, term, tc.encoding) // Same selection must retain all bytes.
			if term.ScreenText() != "old" {
				t.Fatal("fragment prematurely flushed")
			}
			if reset {
				term.ResetOutputStream()
			} else {
				if tc.encoding == EncodingUTF8 {
					setEncoding(t, term, EncodingGBK)
				} else {
					setEncoding(t, term, EncodingUTF8)
				}
			}
			term.WriteString("@")
			if got := term.ScreenText(); got != "old�@" {
				t.Fatalf("%s reset=%v: %q", tc.encoding, reset, got)
			}
			if reset && term.OutputEncoding() != tc.encoding {
				t.Fatal("reset changed selection")
			}
			term.WriteString("\x1b]2;unfinished")
			term.ResetOutputStream()
			term.WriteString("new")
			if term.Title() != "" || term.ScreenText() != "old�@new" {
				t.Fatal("protocol crossed stream boundary")
			}
		}
	}
}

func TestOutputEncodingInvalidControls(t *testing.T) {
	for _, tc := range outputFragments[1:] {
		for _, control := range []string{"\x1b[31m", "\x7f", "\x07", "\r\n"} {
			term := New(40, 2)
			setEncoding(t, term, tc.encoding)
			bells := 0
			term.Bell = func() { bells++ }
			term.WriteString(tc.fragment + control + "X")
			want := "�X"
			if control == "\r\n" {
				want = "�\nX"
			}
			if got := term.ScreenText(); got != want {
				t.Fatalf("%s control %x: %q", tc.encoding, control, got)
			}
			if control == "\x1b[31m" && cell(term, 1, 0).FG != Indexed(1) {
				t.Fatal("ESC swallowed")
			}
			if control == "\x07" && bells != 1 {
				t.Fatal("BEL swallowed")
			}
		}
	}
	for _, tc := range []struct {
		encoding   OutputEncoding
		wire, want string
	}{
		{EncodingGB18030, "\x81\x30\x20X", "�0 X"},
		{EncodingBig5, "\xffX", "�X"}, {EncodingShiftJIS, "\xffX", "�X"},
		{EncodingEUCJP, "\xffX", "�X"}, {EncodingEUCKR, "\xffX", "�X"},
		{EncodingWindows1252, "\x81X", "�X"},
	} {
		term := New(40, 1)
		setEncoding(t, term, tc.encoding)
		term.WriteString(tc.wire)
		if got := term.ScreenText(); got != tc.want {
			t.Fatalf("%s invalid %x: %q", tc.encoding, tc.wire, got)
		}
	}
}

type failingOutputDecoder struct {
	transform.NopResetter
	err error
}

func (d failingOutputDecoder) Transform([]byte, []byte, bool) (int, int, error) { return 0, 0, d.err }

func TestOutputEncodingDecoderError(t *testing.T) {
	term := New(40, 1)
	setEncoding(t, term, EncodingGBK)
	sentinel := errors.New("decoder failure")
	term.outputDecoder = &encoding.Decoder{Transformer: failingOutputDecoder{err: sentinel}}
	if n, err := term.Write([]byte{0x81}); n != 1 || !errors.Is(err, sentinel) {
		t.Fatalf("write: %d %v", n, err)
	}
}
